## 4. Service action changes (plot / edit / delete — Enterprise-gated)

Two new `'use server'` actions in **`apps/web/app/vendor-dashboard/services/actions.ts`**, mirroring the existing `parseDailyCapacityOrThrow` pattern (re-read tier server-side, never trust the form):

```ts
// helper — re-derive tier, throw unless Enterprise
async function assertCanPlotSlots(supabase, vendorProfileId: string) {
  const { data } = await supabase
    .from('vendor_profiles').select('tier_state')
    .eq('vendor_profile_id', vendorProfileId).maybeSingle();
  const tier = asVendorTier((data as { tier_state?: string } | null)?.tier_state ?? null);
  if (!canPlotTimeSlots(tier)) throw new Error('Time slots are an Enterprise feature.');
}

export async function addServiceTimeSlot(formData: FormData) {
  'use server';
  const { supabase, vendorProfileId } = await ensureProfile();
  await assertCanPlotSlots(supabase, vendorProfileId);

  const serviceId = String(formData.get('vendor_service_id') ?? '');
  const label = String(formData.get('slot_label') ?? '').trim();
  const start = String(formData.get('start_time') ?? '');
  const end   = String(formData.get('end_time') ?? '');
  const cap   = Number(formData.get('slot_capacity') ?? 1);

  if (!label || label.length > 80) throw new Error('Slot label required (≤80).');
  if (!/^\d{2}:(00|30)(:00)?$/.test(start) || !/^\d{2}:(00|30)(:00)?$/.test(end))
    throw new Error('Times must be on the hour or half-hour.');
  if (end <= start) throw new Error('End must be after start.');
  if (!Number.isInteger(cap) || cap < 1 || cap > 50) throw new Error('Capacity 1–50.');

  // Ownership: the service must belong to this vendor_profile_id.
  const { data: svc } = await supabase
    .from('vendor_services').select('vendor_service_id')
    .eq('vendor_service_id', serviceId)
    .eq('vendor_profile_id', vendorProfileId).maybeSingle();
  if (!svc) throw new Error('Service not found.');

  const { error } = await supabase.from('vendor_service_time_slots').insert({
    vendor_profile_id: vendorProfileId,   // stamped server-side
    vendor_service_id: serviceId,
    slot_label: label, start_time: start, end_time: end, slot_capacity: cap,
  });
  if (error) throw new Error(error.message);
  revalidatePath('/vendor-dashboard/services');
}

export async function deleteServiceTimeSlot(formData: FormData) {
  'use server';
  const { supabase, vendorProfileId } = await ensureProfile();
  // No tier gate on delete — a downgraded vendor must be able to remove slots.
  const slotId = String(formData.get('slot_id') ?? '');
  const { error } = await supabase
    .from('vendor_service_time_slots')
    .update({ is_active: false, updated_at: new Date().toISOString() })  // soft-deactivate
    .eq('slot_id', slotId)
    .eq('vendor_profile_id', vendorProfileId);  // double-scoped
  if (error) throw new Error(error.message);
  revalidatePath('/vendor-dashboard/services');
}
```

**Edit = delete + add** in V1 (no in-place edit action) to keep build size down; surfaces as "remove this slot, add a new one." (Open Question #6 if owner wants in-place edit.)

The `<input type="time" step={1800}>` front-runs the `:00/:30` CHECK; the server regex + DB CHECK are the real guards.

